// Decode a small binary record without accepting a partial payload.
#[derive(Debug, PartialEq)]
enum DecodeError { Header, Length, Version, NonFinite, Trailing }

struct Record { sequence: u32, values: Vec<f32> }

fn decode(bytes: &[u8]) -> Result<Record, DecodeError> {
    if bytes.len() < 12 { return Err(DecodeError::Header); }
    if &bytes[..4] != b"DATA" { return Err(DecodeError::Header); }
    let version = u16::from_le_bytes([bytes[4], bytes[5]]);
    if version != 2 { return Err(DecodeError::Version); }
    let count = u16::from_le_bytes([bytes[6], bytes[7]]) as usize;
    let sequence = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    let expected = 12usize.checked_add(count.checked_mul(4).ok_or(DecodeError::Length)?)
        .ok_or(DecodeError::Length)?;
    if bytes.len() < expected { return Err(DecodeError::Length); }
    if bytes.len() > expected { return Err(DecodeError::Trailing); }
    let mut values = Vec::with_capacity(count);
    for word in bytes[12..].chunks_exact(4) {
        let value = f32::from_le_bytes(word.try_into().unwrap());
        if !value.is_finite() { return Err(DecodeError::NonFinite); }
        values.push(value);
    }
    Ok(Record { sequence, values })
}

// The zero-length record is valid. A header declaring two values followed by
// only one value is invalid, even if the available value is numerically finite.
// Changing endianness must not be treated as a version upgrade. Test duplicate
// sequence numbers in the caller: that policy is separate from byte decoding.
fn checksum(values: &[f32]) -> f64 {
    values.iter().enumerate().map(|(index, value)|
        (index as f64 + 1.0) * f64::from(*value)).sum()
}
